  const queries=[claim,claim+' official statement independent reporting',claim+' contrary evidence fact check'].slice(0,limit);
  const country=region.toLowerCase().includes('india')?'IN':region.toLowerCase().includes('united states')?'US':region.toLowerCase().includes('united kingdom')?'GB':'ALL';
  const budgets={quick:{urls:'5',tokens:'4096',snippets:'20'},standard:{urls:'12',tokens:'8192',snippets:'50'},deep:{urls:'20',tokens:'16384',snippets:'100'}}[depth]||{urls:'12',tokens:'8192',snippets:'50'};
